import json, csv, os, re, zipfile
import xml.etree.ElementTree as ET

HP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
NS = {"hp": HP_NS}
ET.register_namespace("hp", HP_NS)

# --- Load update data ---
with open('/root/renewal_update.json', 'r', encoding='utf-8') as f:
    updates = json.load(f)

with open('/root/followups.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    followups = sorted(list(reader), key=lambda r: int(r['sequence']))

print('Updates:', json.dumps(updates, ensure_ascii=False, indent=2))
print('Follow-ups:', followups)

# --- Locate section XML(s) ---
base = '/tmp/hwpx_work/original'
section_files = []
for root_dir, dirs, files in os.walk(base):
    for fn in files:
        if fn.endswith('.xml') and fn.startswith('section'):
            section_files.append(os.path.join(root_dir, fn))

section_files = sorted(section_files)
print('Section files:', section_files)


def elem_text_concat(elem):
    """Concatenate all <hp:t> text under elem."""
    texts = []
    for t in elem.findall('.//hp:t', NS):
        if t.text:
            texts.append(t.text)
    return ''.join(texts)


def set_para_text(p_elem, new_text):
    """Set paragraph's visible text by setting first <hp:t> and clearing the rest."""
    t_elems = p_elem.findall('.//hp:t', NS)
    if not t_elems:
        # Minimal structure if missing.
        run = ET.SubElement(p_elem, f'{{{HP_NS}}}run', {"charPrIDRef": "0"})
        t = ET.SubElement(run, f'{{{HP_NS}}}t')
        t.text = new_text
        return

    t_elems[0].text = new_text
    for t in t_elems[1:]:
        t.text = ''


def remove_layout_cache(root_elem):
    """Remove layout cache elements (linesegarray/lineSegArray) anywhere in the tree."""
    target_local_names = {"linesegarray", "lineSegArray", "lineSegArray".lower()}

    def localname(tag):
        if tag.startswith('{'):
            return tag.split('}', 1)[1]
        return tag

    for parent in root_elem.iter():
        for child in list(parent):
            if localname(child.tag) in target_local_names:
                parent.remove(child)


def update_section0(tree, updates):
    root = tree.getroot()

    customer = updates.get('customer', '').strip()
    owner_name = updates.get('owner_name', '').strip()
    window_start = updates.get('window_start', '').strip()
    window_end = updates.get('window_end', '').strip()
    band = updates.get('band', '').strip()
    escalation_email = updates.get('escalation_email', '').strip()
    note = updates.get('note', '').strip()

    for p in root.findall('.//hp:p', NS):
        txt = elem_text_concat(p)
        if txt.startswith('고객사:'):
            set_para_text(p, f'고객사: {customer}')
        elif txt.startswith('현 담당자:'):
            set_para_text(p, f'현 담당자: {owner_name}')
        elif txt.startswith('갱신 윈도우:'):
            set_para_text(p, f'갱신 윈도우: {window_start} ~ {window_end}')
        elif txt.startswith('가격 메모:'):
            set_para_text(p, f'가격 메모: {note}')

    # Update table cells by label
    for tr in root.findall('.//hp:tr', NS):
        tcs = list(tr.findall('hp:tc', NS))
        for i in range(len(tcs) - 1):
            left_txt = elem_text_concat(tcs[i]).strip()
            if '가격 밴드' in left_txt:
                # update right cell's first paragraph
                right_paras = tcs[i+1].findall('.//hp:p', NS)
                if right_paras:
                    set_para_text(right_paras[0], band)
            if '에스컬레이션 연락처' in left_txt:
                right_paras = tcs[i+1].findall('.//hp:p', NS)
                if right_paras:
                    set_para_text(right_paras[0], escalation_email)

    remove_layout_cache(root)


def update_section1(tree, updates, followups):
    root = tree.getroot()

    window_start = updates.get('window_start', '').strip()
    window_end = updates.get('window_end', '').strip()
    appendix_text = '이 부록 문단은 그대로 유지해야 합니다.'

    # Gather paragraphs in document order
    paras = root.findall('.//hp:p', NS)

    # Update follow-up paragraphs: those starting with "1.", "2.", ...
    followup_ps = []
    for p in paras:
        txt = elem_text_concat(p)
        if appendix_text in txt:
            continue
        if re.match(r'^\s*\d+\.', txt):
            followup_ps.append(p)

    print(f'  Follow-up paragraphs detected: {len(followup_ps)}')

    for row in followups:
        seq = int(row['sequence'])
        item = (row.get('item') or '').strip()
        if seq - 1 < len(followup_ps):
            set_para_text(followup_ps[seq - 1], f'{seq}. {item}')

    # Update window confirmation paragraph
    for p in paras:
        txt = elem_text_concat(p)
        if txt.startswith('갱신 윈도우 확인:'):
            set_para_text(p, f'갱신 윈도우 확인: {window_start} ~ {window_end}')

    # Verify appendix remains unchanged (we do not touch it)
    appendix_ok = any(elem_text_concat(p) == appendix_text for p in paras)
    print('  Appendix preserved:', appendix_ok)

    remove_layout_cache(root)


# --- Process each section file ---
for section_file in section_files:
    print(f'\nProcessing: {section_file}')
    tree = ET.parse(section_file)
    root = tree.getroot()

    section_id = root.attrib.get('id', '')
    if section_id == 'section0' or os.path.basename(section_file) == 'section0.xml':
        update_section0(tree, updates)
    else:
        update_section1(tree, updates, followups)

    tree.write(section_file, encoding='UTF-8', xml_declaration=True)
    print('  Written:', section_file)


# --- Repack the HWPX ---
output_path = '/root/renewal_playbook_updated.hwpx'
root_dir = '/tmp/hwpx_work/original'

# Match the original archive entry ordering as best as possible.
preferred_order = [
    'Contents/content.hpf',
    'Contents/section0.xml',
    'Contents/section1.xml',
]

all_files = []
for r, d, files in os.walk(root_dir):
    for fn in files:
        full = os.path.join(r, fn)
        rel = os.path.relpath(full, root_dir).replace('\\', '/')
        all_files.append((rel, full))

# Ensure preferred first, then the rest sorted.
preferred_set = {p for p in preferred_order}
ordered = []
for p in preferred_order:
    for rel, full in all_files:
        if rel == p:
            ordered.append((rel, full))

for rel, full in sorted(all_files, key=lambda x: x[0]):
    if rel not in preferred_set:
        ordered.append((rel, full))

with zipfile.ZipFile(output_path, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
    for rel, full in ordered:
        zf.write(full, rel)

print(f'\nOutput written to {output_path}')
print('Output size:', os.path.getsize(output_path))

with zipfile.ZipFile(output_path, 'r') as zf:
    print('ZIP contents:', zf.namelist())
    bad = zf.testzip()
    print('ZIP integrity:', 'OK' if bad is None else f'BAD FILE: {bad}')

